import{_ as t,o as e,c as r,a3 as o}from"./chunks/framework.BlfGB29P.js";const b=JSON.parse('{"title":"浏览器 Agent","description":"设计浏览器 Agent 的页面感知、动作协议、会话状态、导航验证、下载处理、安全隔离与任务评测。","frontmatter":{"title":"浏览器 Agent","description":"设计浏览器 Agent 的页面感知、动作协议、会话状态、导航验证、下载处理、安全隔离与任务评测。","framework":"Playwright","verified_at":"2026-07-31","source":["https://playwright.dev/python/docs/intro","https://playwright.dev/python/docs/locators","https://playwright.dev/python/docs/actionability","https://genai.owasp.org/llmrisk/llm01-prompt-injection/"],"article":{"type":"concept","structure":"concept"}},"headers":[],"relativePath":"py-agent/architecture/domain-agent-architectures/browser-agent.md","filePath":"py-agent/architecture/domain-agent-architectures/browser-agent.md","lastUpdated":1786083160000}'),n={name:"py-agent/architecture/domain-agent-architectures/browser-agent.md"};function s(i,a,d,l,c,h){return e(),r("div",null,[...a[0]||(a[0]=[o(`<h1 id="浏览器-agent" tabindex="-1">浏览器 Agent <a class="header-anchor" href="#浏览器-agent" aria-label="Permalink to &quot;浏览器 Agent&quot;">​</a></h1><blockquote><p>作者：codex-gpt-sol-5.6</p></blockquote><p>浏览器 Agent 在网页环境中观察、决策并执行导航、点击、输入、提取和下载。它不同于固定 UI 自动化：目标可能开放、页面结构未知、步骤需根据观察调整；但确定性选择器、等待和断言仍应由浏览器自动化层承担，不能全部交给视觉模型猜。</p><p>本章提供浏览器任务的参考架构，不展开 Playwright 百科。外部身份、回调和业务结果对账见<a href="/py-agent/architecture/system-architecture/external-integration-architecture">外部系统集成架构</a>，代码与浏览器执行环境的隔离原则见<a href="/py-agent/quality/security-governance/tool-permissions-sandbox">工具权限与 Sandbox</a>。</p><h2 id="_1-任务边界" tabindex="-1">1. 任务边界 <a class="header-anchor" href="#_1-任务边界" aria-label="Permalink to &quot;1. 任务边界&quot;">​</a></h2><h3 id="_1-1-信息任务" tabindex="-1">1.1 信息任务 <a class="header-anchor" href="#_1-1-信息任务" aria-label="Permalink to &quot;1.1 信息任务&quot;">​</a></h3><p>浏览、搜索、比较和提取，通常只读且风险较低。结果需要来源 URL、页面时间和提取证据。</p><h3 id="_1-2-交互任务" tabindex="-1">1.2 交互任务 <a class="header-anchor" href="#_1-2-交互任务" aria-label="Permalink to &quot;1.2 交互任务&quot;">​</a></h3><p>登录、填写、筛选和上传，可能改变页面会话但未产生最终业务副作用。</p><h3 id="_1-3-执行任务" tabindex="-1">1.3 执行任务 <a class="header-anchor" href="#_1-3-执行任务" aria-label="Permalink to &quot;1.3 执行任务&quot;">​</a></h3><p>下单、发送、删除、提交表单和修改权限。必须在最终动作前服务端授权、参数确认和幂等/业务状态验证。</p><h3 id="_1-4-不适用情况" tabindex="-1">1.4 不适用情况 <a class="header-anchor" href="#_1-4-不适用情况" aria-label="Permalink to &quot;1.4 不适用情况&quot;">​</a></h3><p>有稳定 API 时优先调用 API：契约更清楚、速度更快、错误更可判定。浏览器适合无 API、需理解页面或必须模拟用户界面的场景。</p><h2 id="_2-参考架构" tabindex="-1">2. 参考架构 <a class="header-anchor" href="#_2-参考架构" aria-label="Permalink to &quot;2. 参考架构&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Task API</span></span>
<span class="line"><span>  -&gt; Browser Agent Controller</span></span>
<span class="line"><span>      -&gt; Policy / Approval</span></span>
<span class="line"><span>      -&gt; Observation Builder</span></span>
<span class="line"><span>      -&gt; Model / Planner</span></span>
<span class="line"><span>      -&gt; Browser Tool Adapter</span></span>
<span class="line"><span>          -&gt; Isolated Browser Context</span></span>
<span class="line"><span>      -&gt; Artifact Store (screenshots/downloads)</span></span>
<span class="line"><span>      -&gt; Checkpoint + Trace</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><p>Controller 拥有步数、Deadline 和状态；Browser Adapter 拥有 Playwright 等确定性操作；Policy 决定哪些站点和动作允许。模型不直接接触浏览器进程或宿主文件系统。</p><h2 id="_3-页面感知" tabindex="-1">3. 页面感知 <a class="header-anchor" href="#_3-页面感知" aria-label="Permalink to &quot;3. 页面感知&quot;">​</a></h2><h3 id="_3-1-dom-与可访问性语义" tabindex="-1">3.1 DOM 与可访问性语义 <a class="header-anchor" href="#_3-1-dom-与可访问性语义" aria-label="Permalink to &quot;3.1 DOM 与可访问性语义&quot;">​</a></h3><p>角色、可访问名称、标签、文本和结构比坐标稳定。Playwright 推荐以用户可感知属性定位，例如 <code>get_by_role()</code>、<code>get_by_label()</code>，并通过自动等待检查 Actionability。</p><h3 id="_3-2-精简页面表示" tabindex="-1">3.2 精简页面表示 <a class="header-anchor" href="#_3-2-精简页面表示" aria-label="Permalink to &quot;3.2 精简页面表示&quot;">​</a></h3><p>完整 DOM 过大且包含脚本、样式和隐藏文本。Observation Builder 提取当前 URL、标题、可交互元素、关键文本、可见错误和局部结构，并为元素分配当前观察内稳定 ID。</p><h3 id="_3-3-screenshot-与视觉" tabindex="-1">3.3 Screenshot 与视觉 <a class="header-anchor" href="#_3-3-screenshot-与视觉" aria-label="Permalink to &quot;3.3 Screenshot 与视觉&quot;">​</a></h3><p>Canvas、图表、远程桌面和无语义 UI 需要截图/视觉模型。截图提供像素状态，但坐标易受视口、缩放和布局变化影响；优先语义定位，视觉作为补充或回退。</p><h3 id="_3-4-组合观察" tabindex="-1">3.4 组合观察 <a class="header-anchor" href="#_3-4-组合观察" aria-label="Permalink to &quot;3.4 组合观察&quot;">​</a></h3><p>将 DOM 语义、截图区域、网络/下载事件和历史动作组合，但限制 Token 和敏感内容。每次模型决策记录使用了哪一观察版本。</p><h2 id="_4-动作协议" tabindex="-1">4. 动作协议 <a class="header-anchor" href="#_4-动作协议" aria-label="Permalink to &quot;4. 动作协议&quot;">​</a></h2><h3 id="_4-1-基础动作" tabindex="-1">4.1 基础动作 <a class="header-anchor" href="#_4-1-基础动作" aria-label="Permalink to &quot;4.1 基础动作&quot;">​</a></h3><table tabindex="0"><thead><tr><th>动作</th><th>关键参数</th><th>成功证据</th></tr></thead><tbody><tr><td><code>navigate</code></td><td>允许的 URL</td><td>最终 URL/状态/标题</td></tr><tr><td><code>click</code></td><td>语义 Locator</td><td>导航、状态或元素变化</td></tr><tr><td><code>fill</code></td><td>Locator、文本</td><td>输入值已更新</td></tr><tr><td><code>select</code></td><td>Locator、选项</td><td>选中值</td></tr><tr><td><code>extract</code></td><td>Locator/字段</td><td>结构化结果与来源</td></tr><tr><td><code>download</code></td><td>触发动作</td><td>下载事件、文件哈希</td></tr><tr><td><code>back</code></td><td>无/步数</td><td>历史位置变化</td></tr></tbody></table><p>工具返回结构化观察，不只返回“成功”。</p><h3 id="_4-2-locator-而非任意脚本" tabindex="-1">4.2 Locator 而非任意脚本 <a class="header-anchor" href="#_4-2-locator-而非任意脚本" aria-label="Permalink to &quot;4.2 Locator 而非任意脚本&quot;">​</a></h3><p>模型优先选择受限动作和 Locator，不允许默认执行任意 JavaScript。必须执行脚本的内部工具也应固定模板和参数，避免把模型文本作为代码。</p><h3 id="_4-3-actionability" tabindex="-1">4.3 Actionability <a class="header-anchor" href="#_4-3-actionability" aria-label="Permalink to &quot;4.3 Actionability&quot;">​</a></h3><p>点击前确认元素唯一、可见、稳定、可接收事件且启用。Playwright 会对许多动作自动等待，但业务完成条件仍需显式断言。</p><h3 id="_4-4-动作后验证" tabindex="-1">4.4 动作后验证 <a class="header-anchor" href="#_4-4-动作后验证" aria-label="Permalink to &quot;4.4 动作后验证&quot;">​</a></h3><p>每个动作定义预期变化：URL、标题、元素、网络结果或业务确认号。按钮点击没有抛异常，不代表提交成功。</p><h2 id="_5-决策循环" tabindex="-1">5. 决策循环 <a class="header-anchor" href="#_5-决策循环" aria-label="Permalink to &quot;5. 决策循环&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>observe -&gt; propose action -&gt; policy check -&gt; execute</span></span>
<span class="line"><span>   ^                                      |</span></span>
<span class="line"><span>   |-------- verify / error / new state &lt;-|</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>每步保存目标、观察摘要、动作、参数、策略结果和验证。终止条件包括目标达成、需要人工、权限拒绝、无进展、页面不可恢复、Deadline 和步数/费用耗尽。</p><p>无进展检测可比较 URL、关键页面哈希和动作历史；连续点击同一元素不是有效进展。</p><h2 id="_6-会话与身份" tabindex="-1">6. 会话与身份 <a class="header-anchor" href="#_6-会话与身份" aria-label="Permalink to &quot;6. 会话与身份&quot;">​</a></h2><h3 id="_6-1-browser-context" tabindex="-1">6.1 Browser Context <a class="header-anchor" href="#_6-1-browser-context" aria-label="Permalink to &quot;6.1 Browser Context&quot;">​</a></h3><p>每个租户/任务使用独立 Browser Context，隔离 Cookie、Local Storage 和权限。不要复用管理员日常浏览器 Profile。</p><h3 id="_6-2-登录" tabindex="-1">6.2 登录 <a class="header-anchor" href="#_6-2-登录" aria-label="Permalink to &quot;6.2 登录&quot;">​</a></h3><p>优先通过受控身份流程、短期会话或预先建立的 Storage State。凭据不进入模型上下文，二次认证和验证码通常需要人工介入或正式服务集成。</p><h3 id="_6-3-会话持久化" tabindex="-1">6.3 会话持久化 <a class="header-anchor" href="#_6-3-会话持久化" aria-label="Permalink to &quot;6.3 会话持久化&quot;">​</a></h3><p>长任务可保存受控会话引用和 Agent Checkpoint，但 Cookie/Token 有过期与撤销。恢复后重新验证身份、目标站点和关键业务状态。</p><h2 id="_7-导航与等待" tabindex="-1">7. 导航与等待 <a class="header-anchor" href="#_7-导航与等待" aria-label="Permalink to &quot;7. 导航与等待&quot;">​</a></h2><p>网页是异步状态机，<code>load</code> 事件不等于业务页面完成。等待具体 URL、响应、可见元素或业务文本，避免固定 <code>sleep</code>。</p><p>SPA 导航可能不触发完整页面加载；弹窗、Frame、Shadow DOM 和新 Tab 需要显式作用域。Locator 每次动作重新解析通常比保存旧 Element Handle 更稳。</p><h2 id="_8-下载、上传与文件" tabindex="-1">8. 下载、上传与文件 <a class="header-anchor" href="#_8-下载、上传与文件" aria-label="Permalink to &quot;8. 下载、上传与文件&quot;">​</a></h2><p>下载在隔离目录，限制大小、类型和数量，保存来源 URL、哈希和扫描状态；文件内容是不可信输入。上传只允许任务授权文件，阻止路径穿越和宿主目录访问。</p><p>浏览器任务结束后清理临时文件和上下文；需交付的 Artifact 移入受控对象存储，消息只传引用。</p><h2 id="_9-安全边界" tabindex="-1">9. 安全边界 <a class="header-anchor" href="#_9-安全边界" aria-label="Permalink to &quot;9. 安全边界&quot;">​</a></h2><h3 id="_9-1-间接-prompt-injection" tabindex="-1">9.1 间接 Prompt Injection <a class="header-anchor" href="#_9-1-间接-prompt-injection" aria-label="Permalink to &quot;9.1 间接 Prompt Injection&quot;">​</a></h3><p>网页文本可能诱导 Agent 泄露信息或访问恶意地址。页面内容永远是数据，不能授予权限；模型提议经过工具策略和高风险确认。</p><h3 id="_9-2-网络" tabindex="-1">9.2 网络 <a class="header-anchor" href="#_9-2-网络" aria-label="Permalink to &quot;9.2 网络&quot;">​</a></h3><p>限制协议、域名、解析后 IP、端口、重定向和下载，阻止本地网段、云元数据与管理面。页面可通过子资源和导航尝试绕过，策略应在网络出口执行。</p><h3 id="_9-3-副作用" tabindex="-1">9.3 副作用 <a class="header-anchor" href="#_9-3-副作用" aria-label="Permalink to &quot;9.3 副作用&quot;">​</a></h3><p>发送、购买、删除和发布前显示服务端解析的动作预览；确认绑定参数。页面显示“成功”后再通过业务 ID 或 API 验证。</p><h3 id="_9-4-数据泄露" tabindex="-1">9.4 数据泄露 <a class="header-anchor" href="#_9-4-数据泄露" aria-label="Permalink to &quot;9.4 数据泄露&quot;">​</a></h3><p>剪贴板、下载、上传、表单自动填充和跨站导航都是出口。给任务最小数据，禁止网页读取其他任务 Artifact。</p><h2 id="_10-可靠性与恢复" tabindex="-1">10. 可靠性与恢复 <a class="header-anchor" href="#_10-可靠性与恢复" aria-label="Permalink to &quot;10. 可靠性与恢复&quot;">​</a></h2><p>对超时、元素不唯一、页面变化、登录失效、弹窗、下载失败和连接断开分类。可恢复错误重新观察后有限重试，不用旧坐标盲点。</p><p>写动作遇到模糊结果时先查询业务状态；恢复 Checkpoint 后重新验证页面和副作用。网站 UI 变化通过语义 Locator 契约测试、截图差异和 Canary 发现。</p><h2 id="_11-评测" tabindex="-1">11. 评测 <a class="header-anchor" href="#_11-评测" aria-label="Permalink to &quot;11. 评测&quot;">​</a></h2><p>任务集保存起始环境快照、目标、允许动作、禁止动作和成功 Oracle。指标包括任务成功、合法动作、步数、恢复、时间、每成功任务成本和安全违规。</p><p>在可重置测试站点运行，覆盖动态布局、弹窗、慢网络、登录过期、间接注入和部分成功。只用最终文本 Judge 无法证明网页动作正确。</p><h2 id="_12-贯穿案例-取消待发货订单" tabindex="-1">12. 贯穿案例：取消待发货订单 <a class="header-anchor" href="#_12-贯穿案例-取消待发货订单" aria-label="Permalink to &quot;12. 贯穿案例：取消待发货订单&quot;">​</a></h2><p>场景：用户要求在一个没有正式 API 的供应商门户取消订单 <code>PO-2048</code>。策略只允许访问 <code>portal.example.test</code>，取消动作必须由当前采购员确认。</p><table tabindex="0"><thead><tr><th>阶段</th><th>输入或状态</th><th>结果与证据</th></tr></thead><tbody><tr><td>建立任务</td><td>Principal、订单号、允许域名、Deadline</td><td>创建隔离 Browser Context，不向模型暴露登录凭据</td></tr><tr><td>页面观察</td><td>URL、标题、订单列表的角色与文本</td><td>找到唯一链接“订单 PO-2048”，保存观察版本 <code>obs-01</code></td></tr><tr><td>读取状态</td><td>订单详情显示“待发货”</td><td>提取订单号、供应商、金额和当前状态；页面广告中的指令被当作不可信内容</td></tr><tr><td>提议动作</td><td><code>cancel(order_id=&quot;PO-2048&quot;, reason=&quot;重复采购&quot;)</code></td><td>Policy 判定为写动作，生成规范化预览并进入审批等待</td></tr><tr><td>人工确认</td><td>当前采购员、参数哈希、一次性令牌</td><td>服务端重新验证身份和订单仍为“待发货”</td></tr><tr><td>浏览器执行</td><td>语义 Locator 点击“取消订单”，填写原因并提交</td><td>等待确认页，提取业务回执 <code>CN-8831</code></td></tr><tr><td>结果验证</td><td>刷新订单详情</td><td>状态变为“已取消”，订单号和回执均匹配；保存截图和 Trace 引用</td></tr></tbody></table><p>若提交后连接中断，任务进入“结果待确认”，先重新登录并查询 <code>PO-2048</code> 的业务状态。只有仍为“待发货”且没有取消回执时，才允许重新提议；不能根据最后一次点击没有返回就直接重复提交。</p><p>这个案例把模型和浏览器工具的责任分开：模型根据观察选择下一意图，Playwright 适配器负责 Locator、等待和提取，策略与人工负责写权限，门户状态和回执证明任务完成。</p><h2 id="_13-常见误区" tabindex="-1">13. 常见误区 <a class="header-anchor" href="#_13-常见误区" aria-label="Permalink to &quot;13. 常见误区&quot;">​</a></h2><ol><li><strong>只靠截图坐标</strong>：布局变化即失效。</li><li><strong>点击不报错就是成功</strong>：缺少业务结果验证。</li><li><strong>复用真实用户浏览器</strong>：Cookie、扩展和内网权限扩大风险。</li><li><strong>网页文本是可信指令</strong>：间接注入可控制模型。</li><li><strong>有 API 仍用浏览器</strong>：增加脆弱性和成本。</li></ol><p>浏览器 Agent 的关键是分层：模型负责在开放页面中选择意图，浏览器工具负责确定性定位和执行，策略层限制站点与动作，业务系统证明最终结果。</p>`,75)])])}const u=t(n,[["render",s]]);export{b as __pageData,u as default};
